    pub fn plan_inventory_counts_match(&self) -> bool {
        self.plan.plan_inventory_counts_match()
    }

    /// Return whether replayed row counts agree with their inventories.
    pub fn drain_inventory_counts_match(&self) -> bool {
        self.drain.drain_inventory_counts_match()
    }

    /// Return whether every planned and replayed row count agrees with inventory.
    pub fn inventory_counts_match(&self) -> bool {
        self.plan_inventory_counts_match() && self.drain_inventory_counts_match()
    }

    /// Return whether remaining tick budget agrees with max ticks and drain ticks.
    pub fn remaining_tick_budget_matches_counts(&self) -> bool {
        self.remaining_tick_budget() == self.max_ticks().saturating_sub(self.drain_ticks())
    }

    /// Return whether flattened tick-budget status flags agree with remaining budget.
    pub fn tick_budget_status_flags_match(&self) -> bool {
        self.used_all_ticks() == (self.remaining_tick_budget() == 0)
            && self.has_remaining_tick_budget() == (self.remaining_tick_budget() > 0)
            && self.tick_budget_usage_label_matches_usage()
            && self.used_no_ticks() == (self.drain_ticks() == 0)
            && self.used_partial_tick_budget()
                == (self.drain_ticks() > 0 && self.drain_ticks() < self.max_ticks())
            && self.used_full_tick_budget() == self.used_all_ticks()
            && self.tick_budget_pressure_label_matches_pressure()
            && self.tick_budget_has_slack() == self.tick_budget_pressure().has_slack()
            && self.tick_budget_full_at_end_of_log()
                == self.tick_budget_pressure().is_full_at_end_of_log()
            && self.tick_budget_exhausted_before_end_of_log()
                == self.tick_budget_pressure().is_exhausted_before_end_of_log()
            && self.tick_budget_pressure_requests_continuation()
                == self.tick_budget_pressure().requests_continuation()
            && self.tick_budget_pressure_route_label_matches_route()
            && self.tick_budget_pressure_has_route() == self.tick_budget_pressure().has_route()
            && self.tick_budget_pressure_routes_to_budget_observation()
                == self.tick_budget_pressure().routes_to_budget_observation()
            && self.tick_budget_pressure_routes_to_continuation()
                == self.tick_budget_pressure().routes_to_continuation()
            && self.tick_budget_pressure_priority_label_matches_priority()
            && self.tick_budget_pressure_priority_rank()
                == self.tick_budget_pressure().priority_rank()
            && self.tick_budget_pressure_readiness_label_matches_readiness()
            && self.tick_budget_pressure_is_settled_for_queue()
                == self.tick_budget_pressure().is_settled_for_queue()
            && self.tick_budget_pressure_is_log_only_for_queue()
                == self.tick_budget_pressure().is_log_only_for_queue()
            && self.tick_budget_pressure_is_auto_routable_for_queue()
                == self.tick_budget_pressure().is_auto_routable_for_queue()
            && self.tick_budget_pressure_queue_key_label_matches_key()
            && self.tick_budget_pressure_queue_key_parts_match()
            && !self.has_tick_budget_pressure_queue_key_integrity_drift()
            && self.tick_budget_pressure_queue_labels_match()
            && !self.has_tick_budget_pressure_queue_label_integrity_drift()
            && self.tick_budget_pressure_rollup_key_label_matches_key()
            && self.tick_budget_pressure_rollup_key_parts_match()
            && self.tick_budget_pressure_rollup_key_matches_queue_key()
            && !self.has_tick_budget_pressure_rollup_key_integrity_drift()
            && self.tick_budget_pressure_queue_digest_label_matches_digest()
            && self.tick_budget_pressure_queue_digest_parts_match()
            && self.tick_budget_pressure_queue_digest_matches_queue_key()
            && self.tick_budget_pressure_queue_digest_matches_rollup_key()
            && !self.has_tick_budget_pressure_queue_digest_integrity_drift()
            && self.tick_budget_pressure_queue_digest_labels_match()
            && !self.has_tick_budget_pressure_queue_digest_label_integrity_drift()
    }

    /// Return whether flattened drain status flags agree with source counts.
    pub fn drain_status_flags_match(&self) -> bool {
        self.is_idle() == (self.drained_records() == 0)
            && self.made_progress() == (self.drained_records() > 0)
            && self.should_continue() != self.reached_end_of_log()
            && self.exhausted_tick_budget()
                == (self.drain_ticks() == self.max_ticks() && !self.reached_end_of_log())
            && self.advanced_checkpoint() == self.made_progress()
    }

    /// Return whether all flattened budget and status flags agree with sources.
    pub fn run_status_flags_match(&self) -> bool {
        self.remaining_tick_budget_matches_counts()
            && self.tick_budget_status_flags_match()
            && self.drain_status_flags_match()
    }

