/// Aggregate plan/drain health surface for supervisor drain host dashboards.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolAuditSupervisorDrainHealthDashboardSurface {
    /// Neither the preflight plan nor the drain result needs health action.
    Settled,
    /// The preflight plan needs health action.
    PlanAction,
    /// The drain result needs health action.
    DrainAction,
    /// Both the preflight plan and drain result need health action.
    PlanAndDrainAction,
}

impl ToolAuditSupervisorDrainHealthDashboardSurface {
    /// Classify aggregate health actionability from plan and drain flags.
    pub fn from_surface_flags(plan_is_actionable: bool, drain_is_actionable: bool) -> Self {
        match (plan_is_actionable, drain_is_actionable) {
            (false, false) => Self::Settled,
            (true, false) => Self::PlanAction,
            (false, true) => Self::DrainAction,
            (true, true) => Self::PlanAndDrainAction,
        }
    }

    /// Return a stable snake_case label for host dashboards.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Settled => "settled",
            Self::PlanAction => "plan_action",
            Self::DrainAction => "drain_action",
            Self::PlanAndDrainAction => "plan_and_drain_action",
        }
    }

    /// Parse a stable snake_case health-dashboard surface label.
    pub fn from_label(label: &str) -> Option<Self> {
        match label {
            "settled" => Some(Self::Settled),
            "plan_action" => Some(Self::PlanAction),
            "drain_action" => Some(Self::DrainAction),
            "plan_and_drain_action" => Some(Self::PlanAndDrainAction),
            _ => None,
        }
    }

    /// Return whether no aggregate health surface needs action.
    pub fn is_settled(self) -> bool {
        matches!(self, Self::Settled)
    }

    /// Return whether the preflight plan contributes action pressure.
    pub fn has_plan_action(self) -> bool {
        matches!(self, Self::PlanAction | Self::PlanAndDrainAction)
    }

    /// Return whether the drain result contributes action pressure.
    pub fn has_drain_action(self) -> bool {
        matches!(self, Self::DrainAction | Self::PlanAndDrainAction)
    }

    /// Return how many aggregate health surfaces need action.
    pub fn action_count(self) -> usize {
        [self.has_plan_action(), self.has_drain_action()]
            .into_iter()
            .filter(|is_active| *is_active)
            .count()
    }

    /// Return whether more than one aggregate health surface needs action.
    pub fn has_multiple_actions(self) -> bool {
        matches!(self, Self::PlanAndDrainAction)
    }
}

impl Display for ToolAuditSupervisorDrainHealthDashboardSurface {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Stable aggregate action lane for supervisor drain health dashboards.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolAuditSupervisorDrainHealthDashboardActionLane {
    /// No aggregate health action is needed.
    NoAction,
    /// The only aggregate health action is draining checkpoint pages.
    Drain,
    /// The only aggregate health action is routing follow-up pressure.
    FollowUp,
    /// The only aggregate health action is scheduling continuation.
    Continuation,
    /// The only aggregate health action is investigation.
    Investigation,
    /// Multiple aggregate health action lanes are active.
    Mixed,
}

impl ToolAuditSupervisorDrainHealthDashboardActionLane {
    /// Classify the aggregate health-dashboard action lane from component flags.
    pub fn from_action_flags(
        should_drain_page: bool,
        routes_follow_up: bool,
        requests_continuation: bool,
        requires_investigation: bool,
    ) -> Self {
        match [
            should_drain_page,
            routes_follow_up,
            requests_continuation,
            requires_investigation,
        ]
        .into_iter()
        .filter(|is_active| *is_active)
        .count()
        {
            0 => Self::NoAction,
            1 if should_drain_page => Self::Drain,
            1 if routes_follow_up => Self::FollowUp,
            1 if requests_continuation => Self::Continuation,
            1 if requires_investigation => Self::Investigation,
            _ => Self::Mixed,
        }
    }

    /// Return a stable snake_case label for logs and dashboard grouping.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::NoAction => "no_action",
            Self::Drain => "drain",
            Self::FollowUp => "follow_up",
            Self::Continuation => "continuation",
            Self::Investigation => "investigation",
            Self::Mixed => "mixed",
        }
    }

    /// Parse a stable snake_case health-dashboard action lane label.
    pub fn from_label(label: &str) -> Option<Self> {
        match label {
            "no_action" => Some(Self::NoAction),
            "drain" => Some(Self::Drain),
            "follow_up" => Some(Self::FollowUp),
            "continuation" => Some(Self::Continuation),
            "investigation" => Some(Self::Investigation),
            "mixed" => Some(Self::Mixed),
            _ => None,
        }
    }

    /// Return whether no aggregate health action is needed.
    pub fn is_no_action(self) -> bool {
        matches!(self, Self::NoAction)
    }

    /// Return whether this is the drain action lane.
    pub fn is_drain(self) -> bool {
        matches!(self, Self::Drain)
    }

    /// Return whether this is the follow-up action lane.
    pub fn is_follow_up(self) -> bool {
        matches!(self, Self::FollowUp)
    }

    /// Return whether this is the continuation action lane.
    pub fn is_continuation(self) -> bool {
        matches!(self, Self::Continuation)
    }

    /// Return whether this is the investigation action lane.
    pub fn is_investigation(self) -> bool {
        matches!(self, Self::Investigation)
    }

    /// Return whether multiple aggregate health action lanes are active.
    pub fn is_mixed(self) -> bool {
        matches!(self, Self::Mixed)
    }
}

impl Display for ToolAuditSupervisorDrainHealthDashboardActionLane {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Stable composite queue key for supervisor drain health dashboards.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ToolAuditSupervisorDrainHealthDashboardQueueKey {
    surface: ToolAuditSupervisorDrainHealthDashboardSurface,
    action_lane: ToolAuditSupervisorDrainHealthDashboardActionLane,
    route: ToolAuditHealthRoute,
    priority: ToolAuditHealthPriority,
    readiness: ToolAuditHealthReadiness,
}

impl ToolAuditSupervisorDrainHealthDashboardQueueKey {
    /// Create a stable health-dashboard queue key from typed classifier values.
    pub fn new(
        surface: ToolAuditSupervisorDrainHealthDashboardSurface,
        action_lane: ToolAuditSupervisorDrainHealthDashboardActionLane,
        route: ToolAuditHealthRoute,
        priority: ToolAuditHealthPriority,
        readiness: ToolAuditHealthReadiness,
    ) -> Self {
        Self {
            surface,
            action_lane,
            route,
            priority,
            readiness,
        }
    }

    /// Parse a stable health-dashboard queue-key label.
    pub fn from_label(label: &str) -> Option<Self> {
        let mut parts = label.split(':');
        let surface = ToolAuditSupervisorDrainHealthDashboardSurface::from_label(parts.next()?)?;
        let action_lane =
            ToolAuditSupervisorDrainHealthDashboardActionLane::from_label(parts.next()?)?;
        let route = ToolAuditHealthRoute::from_label(parts.next()?)?;
        let priority = ToolAuditHealthPriority::from_label(parts.next()?)?;
        let readiness = ToolAuditHealthReadiness::from_label(parts.next()?)?;
        if parts.next().is_some() {
            return None;
        }
        Some(Self::new(surface, action_lane, route, priority, readiness))
    }

    /// Return the aggregate health-dashboard surface.
    pub fn surface(self) -> ToolAuditSupervisorDrainHealthDashboardSurface {
        self.surface
    }

    /// Return the aggregate health-dashboard action lane.
    pub fn action_lane(self) -> ToolAuditSupervisorDrainHealthDashboardActionLane {
        self.action_lane
    }

    /// Return the aggregate health-dashboard queue route.
    pub fn route(self) -> ToolAuditHealthRoute {
        self.route
    }

    /// Return the aggregate health-dashboard priority.
    pub fn priority(self) -> ToolAuditHealthPriority {
        self.priority
    }

    /// Return the aggregate health-dashboard readiness.
    pub fn readiness(self) -> ToolAuditHealthReadiness {
        self.readiness
    }

    /// Return a stable composite label for host queue grouping.
    pub fn label(self) -> String {
        format!(
            "{}:{}:{}:{}:{}",
            self.surface.as_str(),
            self.action_lane.as_str(),
            self.route.as_str(),
            self.priority.as_str(),
            self.readiness.as_str()
        )
    }

    /// Return whether this queue-key label parses back to this typed key.
    pub fn label_matches_key(self) -> bool {
        Self::from_label(&self.label()) == Some(self)
    }

    /// Return the sortable priority rank for this queue key.
    pub fn priority_rank(self) -> u8 {
        self.priority.rank()
    }

    /// Return whether this queue key represents settled aggregate health.
    pub fn is_settled(self) -> bool {
        self.surface.is_settled()
            && self.action_lane.is_no_action()
            && !self.route.has_route()
            && self.priority.is_settled()
            && self.readiness.is_settled()
    }

    /// Return whether this queue key should appear in an action queue.
    pub fn is_actionable(self) -> bool {
        self.readiness.is_actionable()
    }

    /// Return whether this queue key can be routed without manual review.
    pub fn is_auto_routable(self) -> bool {
        self.readiness.is_auto_routable()
    }

    /// Return whether this queue key needs manual review.
    pub fn requires_manual_review(self) -> bool {
        self.readiness.requires_manual_review()
    }

    /// Return whether this queue key needs investigation.
    pub fn requires_investigation(self) -> bool {
        self.readiness.requires_investigation()
    }

    /// Return whether this queue key needs triage.
    pub fn requires_triage(self) -> bool {
        self.readiness.requires_triage()
    }

    /// Return whether this queue key's surface matches the supplied surface.
    pub fn surface_matches(self, surface: ToolAuditSupervisorDrainHealthDashboardSurface) -> bool {
        self.surface == surface
    }

    /// Return whether this queue key's action lane matches the supplied lane.
    pub fn action_lane_matches(
        self,
        action_lane: ToolAuditSupervisorDrainHealthDashboardActionLane,
    ) -> bool {
        self.action_lane == action_lane
    }

    /// Return whether this queue key's route matches the supplied route.
    pub fn route_matches(self, route: ToolAuditHealthRoute) -> bool {
        self.route == route
    }

    /// Return whether this queue key's priority matches the supplied priority.
    pub fn priority_matches(self, priority: ToolAuditHealthPriority) -> bool {
        self.priority == priority
    }

    /// Return whether this queue key's readiness matches the supplied readiness.
    pub fn readiness_matches(self, readiness: ToolAuditHealthReadiness) -> bool {
        self.readiness == readiness
    }

    /// Return whether every queue-key component matches the supplied dashboard digest.
    pub fn parts_match(
        self,
        surface: ToolAuditSupervisorDrainHealthDashboardSurface,
        action_lane: ToolAuditSupervisorDrainHealthDashboardActionLane,
        route: ToolAuditHealthRoute,
        priority: ToolAuditHealthPriority,
        readiness: ToolAuditHealthReadiness,
    ) -> bool {
        self.surface_matches(surface)
            && self.action_lane_matches(action_lane)
            && self.route_matches(route)
            && self.priority_matches(priority)
            && self.readiness_matches(readiness)
    }
}

impl Display for ToolAuditSupervisorDrainHealthDashboardQueueKey {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.write_str(&self.label())
    }
}

/// Scheduler-facing classification for a bounded supervisor drain run.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolAuditSupervisorDrainRunOutcome {
    /// No rows were waiting and the checkpoint stayed untouched.
    Idle,
    /// Rows were replayed and the drain reached the current end of the log.
    CaughtUp,
    /// The tick budget was exhausted before reaching the end of the log.
    NeedsContinuation,
    /// Planned or replayed rows contain follow-up pressure.
    NeedsFollowUp,
    /// The preflight plan and actual drain delivered different row counts.
    PlanDiverged,
}

impl ToolAuditSupervisorDrainRunOutcome {
    /// Return a stable snake_case label for logs and host summaries.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Idle => "idle",
            Self::CaughtUp => "caught_up",
            Self::NeedsContinuation => "needs_continuation",
            Self::NeedsFollowUp => "needs_follow_up",
            Self::PlanDiverged => "plan_diverged",
        }
    }

    /// Parse a stable snake_case outcome label.
    pub fn from_label(label: &str) -> Option<Self> {
        match label {
            "idle" => Some(Self::Idle),
            "caught_up" => Some(Self::CaughtUp),
            "needs_continuation" => Some(Self::NeedsContinuation),
            "needs_follow_up" => Some(Self::NeedsFollowUp),
            "plan_diverged" => Some(Self::PlanDiverged),
            _ => None,
        }
    }

    /// Return whether no rows were waiting and the checkpoint stayed untouched.
    pub fn is_idle(self) -> bool {
        matches!(self, Self::Idle)
    }

    /// Return whether rows were replayed and the run reached the current log end.
    pub fn is_caught_up(self) -> bool {
        matches!(self, Self::CaughtUp)
    }

    /// Return whether this outcome stopped before reaching the current log end.
    pub fn needs_continuation(self) -> bool {
        matches!(self, Self::NeedsContinuation)
    }

    /// Return whether this outcome contains follow-up pressure.
    pub fn needs_follow_up(self) -> bool {
        matches!(self, Self::NeedsFollowUp)
    }

    /// Return whether the preflight plan and actual drain counts diverged.
    pub fn plan_diverged(self) -> bool {
        matches!(self, Self::PlanDiverged)
    }

    /// Return whether the scheduler should take action for this outcome.
    pub fn requires_scheduler_action(self) -> bool {
        self.scheduler_action().requires_scheduler_action()
    }

    /// Return whether this outcome intentionally leaves the scheduler idle.
    pub fn is_no_scheduler_action(self) -> bool {
        self.scheduler_action().is_no_action()
    }

    /// Return the recommended scheduler action for this outcome.
    pub fn scheduler_action(self) -> ToolAuditSupervisorDrainSchedulerAction {
        match self {
            Self::Idle | Self::CaughtUp => ToolAuditSupervisorDrainSchedulerAction::NoAction,
            Self::NeedsContinuation => {
                ToolAuditSupervisorDrainSchedulerAction::ScheduleContinuation
            }
            Self::NeedsFollowUp => ToolAuditSupervisorDrainSchedulerAction::RouteFollowUp,
            Self::PlanDiverged => ToolAuditSupervisorDrainSchedulerAction::InvestigatePlanDrift,
        }
    }

    /// Return the stable scheduler-action label for this outcome.
    pub fn scheduler_action_label(self) -> &'static str {
        self.scheduler_action().as_str()
    }

    /// Return whether this outcome asks the host to schedule another drain pass.
    pub fn requests_continuation(self) -> bool {
        self.scheduler_action().requests_continuation()
    }

    /// Return whether this outcome routes follow-up pressure to the host.
    pub fn routes_follow_up(self) -> bool {
        self.scheduler_action().routes_follow_up()
    }

    /// Return whether this outcome asks the host to investigate plan drift.
    pub fn requires_plan_drift_investigation(self) -> bool {
        self.scheduler_action().requires_plan_drift_investigation()
    }
}

impl Display for ToolAuditSupervisorDrainRunOutcome {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Scheduler recommendation derived from a bounded supervisor drain outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolAuditSupervisorDrainSchedulerAction {
    /// The run is terminal for now and needs no scheduler follow-up.
    NoAction,
    /// Schedule another bounded drain pass from the advanced checkpoint.
    ScheduleContinuation,
    /// Route replayed or planned follow-up pressure to the supervising host.
    RouteFollowUp,
    /// Investigate a mismatch between the preflight plan and actual drain.
    InvestigatePlanDrift,
}

impl ToolAuditSupervisorDrainSchedulerAction {
    /// Return a stable snake_case label for logs and host summaries.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::NoAction => "no_action",
            Self::ScheduleContinuation => "schedule_continuation",
            Self::RouteFollowUp => "route_follow_up",
            Self::InvestigatePlanDrift => "investigate_plan_drift",
        }
    }

    /// Parse a stable snake_case scheduler action label.
    pub fn from_label(label: &str) -> Option<Self> {
        match label {
            "no_action" => Some(Self::NoAction),
            "schedule_continuation" => Some(Self::ScheduleContinuation),
            "route_follow_up" => Some(Self::RouteFollowUp),
            "investigate_plan_drift" => Some(Self::InvestigatePlanDrift),
            _ => None,
        }
    }

    /// Return whether the host scheduler needs to take an explicit action.
    pub fn requires_scheduler_action(self) -> bool {
        !matches!(self, Self::NoAction)
    }

    /// Return whether this action intentionally leaves the scheduler idle.
    pub fn is_no_action(self) -> bool {
        matches!(self, Self::NoAction)
    }

    /// Return whether this action asks the host to schedule another drain pass.
    pub fn requests_continuation(self) -> bool {
        matches!(self, Self::ScheduleContinuation)
    }

    /// Return whether this action routes follow-up pressure to the host.
    pub fn routes_follow_up(self) -> bool {
        matches!(self, Self::RouteFollowUp)
    }

    /// Return whether this action asks the host to investigate plan drift.
    pub fn requires_plan_drift_investigation(self) -> bool {
        matches!(self, Self::InvestigatePlanDrift)
    }
}

impl Display for ToolAuditSupervisorDrainSchedulerAction {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Stable host route derived from a bounded supervisor drain outcome.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ToolAuditSupervisorDrainRunOutcomeRoute {
    /// The outcome does not need a host route.
    NoRoute,
    /// The host should schedule another bounded drain pass.
    Continuation,
    /// The host should route follow-up pressure.
    FollowUp,
    /// The host should investigate plan drift.
    PlanDriftInvestigation,
}

impl ToolAuditSupervisorDrainRunOutcomeRoute {
    /// Classify the outcome route from a scheduler action.
    pub fn from_scheduler_action(action: ToolAuditSupervisorDrainSchedulerAction) -> Self {
        match action {
            ToolAuditSupervisorDrainSchedulerAction::NoAction => Self::NoRoute,
            ToolAuditSupervisorDrainSchedulerAction::ScheduleContinuation => Self::Continuation,
            ToolAuditSupervisorDrainSchedulerAction::RouteFollowUp => Self::FollowUp,
            ToolAuditSupervisorDrainSchedulerAction::InvestigatePlanDrift => {
                Self::PlanDriftInvestigation
            }
        }
    }

    /// Return a stable snake_case route label for host logs.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::NoRoute => "no_route",
            Self::Continuation => "continuation",
            Self::FollowUp => "follow_up",
            Self::PlanDriftInvestigation => "plan_drift_investigation",
        }
    }

    /// Parse a stable outcome-route label.
    pub fn from_label(label: &str) -> Option<Self> {
        match label {
            "no_route" => Some(Self::NoRoute),
            "continuation" => Some(Self::Continuation),
            "follow_up" => Some(Self::FollowUp),
            "plan_drift_investigation" => Some(Self::PlanDriftInvestigation),
            _ => None,
        }
    }

    /// Return whether this route intentionally leaves the host idle.
    pub fn is_no_route(self) -> bool {
        matches!(self, Self::NoRoute)
    }

    /// Return whether this route points to a concrete host action.
    pub fn has_route(self) -> bool {
        !self.is_no_route()
    }

    /// Return whether this route can be handled without manual investigation.
    pub fn is_auto_routable(self) -> bool {
        matches!(self, Self::NoRoute | Self::Continuation | Self::FollowUp)
    }

    /// Return whether this route asks for another drain pass.
    pub fn routes_to_continuation(self) -> bool {
        matches!(self, Self::Continuation)
    }

    /// Return whether this route asks the host to route follow-up pressure.
    pub fn routes_to_follow_up(self) -> bool {
        matches!(self, Self::FollowUp)
    }

    /// Return whether this route asks the host to investigate plan drift.
    pub fn routes_to_plan_drift_investigation(self) -> bool {
        matches!(self, Self::PlanDriftInvestigation)
    }

    /// Return whether this route needs host investigation.
    pub fn requires_investigation(self) -> bool {
        self.routes_to_plan_drift_investigation()
    }
}

