/// Payload-free summary for a batch audit write.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct ToolAuditBatchWriteSummary {
    /// Number of rows attempted.
    pub attempted_records: usize,
    /// Number of rows persisted.
    pub stored_records: usize,
    /// Number of rows that failed to persist.
    pub failed_records: usize,
    /// Payload-free summary of successfully persisted rows.
    pub inventory: ToolAuditStoreInventorySummary,
    /// Storage failures captured by call id.
    pub failures: Vec<ToolAuditSinkFailure>,
}

impl ToolAuditBatchWriteSummary {
    /// Construct an empty batch summary.
    pub fn empty() -> Self {
        Self::default()
    }

    /// Return whether the batch had no rows.
    pub fn is_empty(&self) -> bool {
        self.attempted_records == 0
    }

    /// Return whether any audit rows were persisted.
    pub fn has_stored_records(&self) -> bool {
        self.stored_records > 0
    }

    /// Return whether any audit row failed to persist.
    pub fn has_storage_failures(&self) -> bool {
        self.failed_records > 0 || !self.failures.is_empty()
    }

    /// Return whether the stored row count matches the payload-free inventory.
    pub fn stored_count_matches_inventory(&self) -> bool {
        self.stored_records == self.inventory.total_records
    }

    /// Return whether the failed row count matches the captured failures.
    pub fn failed_count_matches_failures(&self) -> bool {
        self.failed_records == self.failures.len()
    }

    /// Return whether attempted rows equal stored plus failed rows.
    pub fn attempted_count_matches_results(&self) -> bool {
        self.stored_records.checked_add(self.failed_records) == Some(self.attempted_records)
    }

    /// Return whether all flattened write counts agree with their sources.
    pub fn write_counts_match(&self) -> bool {
        self.attempted_count_matches_results()
            && self.stored_count_matches_inventory()
            && self.failed_count_matches_failures()
    }

    /// Return whether flattened write counts drifted from their sources.
    pub fn has_write_count_integrity_drift(&self) -> bool {
        !self.write_counts_match()
    }

    /// Classify follow-up pressure in the persisted row inventory.
    pub fn inventory_follow_up_kind(&self) -> ToolAuditInventoryFollowUpKind {
        self.inventory.follow_up_kind()
    }

    /// Return the stable follow-up label for the persisted row inventory.
    pub fn inventory_follow_up_label(&self) -> &'static str {
        self.inventory.follow_up_label()
    }

    /// Return whether the inventory follow-up label parses back to its typed value.
    pub fn inventory_follow_up_label_matches_kind(&self) -> bool {
        self.inventory.follow_up_label_matches_kind()
    }

    /// Classify the payload-free outcome of this batch write.
    pub fn write_outcome(&self) -> ToolAuditBatchWriteOutcome {
        ToolAuditBatchWriteOutcome::from_write_summary(self)
    }

    /// Return the stable batch-write outcome label for host logs.
    pub fn write_outcome_label(&self) -> &'static str {
        self.write_outcome().as_str()
    }

    /// Return whether the batch-write outcome label parses back to its typed value.
    pub fn write_outcome_label_matches_outcome(&self) -> bool {
        ToolAuditBatchWriteOutcome::from_label(self.write_outcome_label())
            == Some(self.write_outcome())
    }

    /// Return whether all batch-write health labels match their typed values.
    pub fn health_labels_match(&self) -> bool {
        self.inventory_follow_up_label_matches_kind()
            && self.write_outcome_label_matches_outcome()
            && self.health_action_label_matches_action()
            && self.health_route_label_matches_route()
            && self.health_priority_label_matches_priority()
            && self.health_readiness_label_matches_readiness()
    }

    /// Return whether any batch-write health label drifted from its classifier.
    pub fn has_health_label_integrity_drift(&self) -> bool {
        !self.health_labels_match()
    }

    /// Return the recommended host action for this batch-write health.
    pub fn health_action(&self) -> ToolAuditHealthAction {
        self.write_outcome().health_action()
    }

    /// Return the stable health-action label for host logs.
    pub fn health_action_label(&self) -> &'static str {
        self.health_action().as_str()
    }

    /// Return whether the health-action label parses back to its typed action.
    pub fn health_action_label_matches_action(&self) -> bool {
        ToolAuditHealthAction::from_label(self.health_action_label()) == Some(self.health_action())
    }

    /// Return whether this batch write needs any host health action.
    pub fn requires_health_action(&self) -> bool {
        self.health_action().requires_action()
    }

    /// Return whether this batch write routes follow-up pressure.
    pub fn health_action_routes_follow_up(&self) -> bool {
        self.health_action().routes_follow_up()
    }

    /// Return whether this batch write needs storage failure investigation.
    pub fn health_action_requires_storage_investigation(&self) -> bool {
        self.health_action().requires_storage_investigation()
    }

    /// Return whether this batch write needs count-integrity investigation.
    pub fn health_action_requires_count_integrity_investigation(&self) -> bool {
        self.health_action()
            .requires_count_integrity_investigation()
    }

    /// Return the host route for this batch-write health.
    pub fn health_route(&self) -> ToolAuditHealthRoute {
        self.health_action().route()
    }

    /// Return the stable health-route label for host logs.
    pub fn health_route_label(&self) -> &'static str {
        self.health_route().as_str()
    }

    /// Return whether the health-route label parses back to its typed route.
    pub fn health_route_label_matches_route(&self) -> bool {
        ToolAuditHealthRoute::from_label(self.health_route_label()) == Some(self.health_route())
    }

    /// Return whether this batch write has a concrete health route.
    pub fn health_has_route(&self) -> bool {
        self.health_route().has_route()
    }

    /// Return whether this batch write routes health follow-up.
    pub fn health_routes_to_follow_up(&self) -> bool {
        self.health_route().is_follow_up()
    }

    /// Return whether this batch write routes to storage investigation.
    pub fn health_routes_to_storage_investigation(&self) -> bool {
        self.health_route().is_storage_investigation()
    }

    /// Return whether this batch write routes to count-integrity investigation.
    pub fn health_routes_to_count_integrity_investigation(&self) -> bool {
        self.health_route().is_count_integrity_investigation()
    }

    /// Return whether this batch write routes health investigation work.
    pub fn health_routes_to_investigation(&self) -> bool {
        self.health_route().is_investigation()
    }

    /// Classify dashboard priority for this batch-write health.
    pub fn health_priority(&self) -> ToolAuditHealthPriority {
        self.health_action().priority()
    }

    /// Return the stable health-priority label for host logs.
    pub fn health_priority_label(&self) -> &'static str {
        self.health_priority().as_str()
    }

    /// Return whether the health-priority label parses back to its typed priority.
    pub fn health_priority_label_matches_priority(&self) -> bool {
        ToolAuditHealthPriority::from_label(self.health_priority_label())
            == Some(self.health_priority())
    }

    /// Return the sortable health-priority rank.
    pub fn health_priority_rank(&self) -> u8 {
        self.health_priority().rank()
    }

    /// Return whether this batch-write health has investigation priority.
    pub fn health_has_investigation_priority(&self) -> bool {
        self.health_priority().requires_investigation()
    }

    /// Return whether this batch-write health priority requires triage.
    pub fn health_priority_requires_triage(&self) -> bool {
        self.health_priority().requires_triage()
    }

    /// Classify queue readiness for this batch-write health.
    pub fn health_readiness(&self) -> ToolAuditHealthReadiness {
        self.health_action().readiness()
    }

    /// Return the stable health-readiness label for host logs.
    pub fn health_readiness_label(&self) -> &'static str {
        self.health_readiness().as_str()
    }

    /// Return whether the health-readiness label parses back to its typed readiness.
    pub fn health_readiness_label_matches_readiness(&self) -> bool {
        ToolAuditHealthReadiness::from_label(self.health_readiness_label())
            == Some(self.health_readiness())
    }

    /// Return whether this batch-write health should appear in an action queue.
    pub fn health_is_actionable(&self) -> bool {
        self.health_readiness().is_actionable()
    }

    /// Return whether this batch-write health can be routed automatically.
    pub fn health_is_auto_routable(&self) -> bool {
        self.health_readiness().is_auto_routable()
    }

    /// Return whether this batch-write health needs manual review.
    pub fn health_readiness_requires_manual_review(&self) -> bool {
        self.health_readiness().requires_manual_review()
    }

    /// Return whether this batch-write health needs investigation.
    pub fn health_readiness_requires_investigation(&self) -> bool {
        self.health_readiness().requires_investigation()
    }

    /// Return whether this batch-write health needs triage.
    pub fn health_readiness_requires_triage(&self) -> bool {
        self.health_readiness().requires_triage()
    }

    /// Return whether every attempted row was persisted.
    pub fn completed_without_failures(&self) -> bool {
        self.attempted_records == self.stored_records && self.failed_records == 0
    }

    /// Return whether any persisted row or storage failure needs follow-up.
    pub fn requires_follow_up(&self) -> bool {
        self.has_storage_failures() || self.inventory.requires_follow_up()
    }
}

