        assert_eq!(summary.outcome_digest_label, outcome_digest_label);
        assert_eq!(
            summary.outcome_digest_label(),
            outcome_digest_label.as_str()
        );
        assert!(summary.outcome_digest_labels_match);
        assert!(summary.outcome_digest_labels_match());
