    #[test]
    fn supervisor_drain_host_run_escalation_kinds_are_stable() {
        let settled_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::NoAttention,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::NoRoute,
                ToolAuditSupervisorDrainHostRunActionLane::NoAction,
                ToolAuditSupervisorDrainHostRunQueuePriority::Settled,
                ToolAuditSupervisorDrainHostRunQueueReadiness::Settled,
            ),
        );
        let routine_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::HealthDashboardAction,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::HealthDashboard,
                ToolAuditSupervisorDrainHostRunActionLane::Drain,
                ToolAuditSupervisorDrainHostRunQueuePriority::RoutineAction,
                ToolAuditSupervisorDrainHostRunQueueReadiness::RoutineReady,
            ),
        );
        let manual_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::NoAttention,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::HealthDashboard,
                ToolAuditSupervisorDrainHostRunActionLane::Drain,
                ToolAuditSupervisorDrainHostRunQueuePriority::ManualReview,
                ToolAuditSupervisorDrainHostRunQueueReadiness::ManualReviewReady,
            ),
        );
        let investigation_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::NoAttention,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::HostDecision,
                ToolAuditSupervisorDrainHostRunActionLane::Investigation,
                ToolAuditSupervisorDrainHostRunQueuePriority::Investigation,
                ToolAuditSupervisorDrainHostRunQueueReadiness::InvestigationReady,
            ),
        );
        let integrity_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::NoAttention,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::HostDecision,
                ToolAuditSupervisorDrainHostRunActionLane::Investigation,
                ToolAuditSupervisorDrainHostRunQueuePriority::IntegrityInvestigation,
                ToolAuditSupervisorDrainHostRunQueueReadiness::IntegrityInvestigationReady,
            ),
        );
        let triage_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::HealthDashboardActionAndSchedulerAction,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::SplitQueues,
                ToolAuditSupervisorDrainHostRunActionLane::Mixed,
                ToolAuditSupervisorDrainHostRunQueuePriority::Triage,
                ToolAuditSupervisorDrainHostRunQueueReadiness::TriageRequired,
            ),
        );

        let cases = [
            (
                settled_key,
                ToolAuditSupervisorDrainHostRunEscalationKind::Settled,
                "settled",
                0,
            ),
            (
                routine_key,
                ToolAuditSupervisorDrainHostRunEscalationKind::RoutineAction,
                "routine_action",
                20,
            ),
            (
                manual_key,
                ToolAuditSupervisorDrainHostRunEscalationKind::ManualReview,
                "manual_review",
                60,
            ),
            (
                investigation_key,
                ToolAuditSupervisorDrainHostRunEscalationKind::Investigation,
                "investigation",
                70,
            ),
            (
                integrity_key,
                ToolAuditSupervisorDrainHostRunEscalationKind::IntegrityInvestigation,
                "integrity_investigation",
                80,
            ),
            (
                triage_key,
                ToolAuditSupervisorDrainHostRunEscalationKind::Triage,
                "triage",
                90,
            ),
        ];

        for (key, expected_kind, expected_label, expected_rank) in cases {
            let kind = ToolAuditSupervisorDrainHostRunEscalationKind::from_supervision_key(key);
            assert_eq!(kind, expected_kind);
            assert_eq!(kind.as_str(), expected_label);
            assert_eq!(
                ToolAuditSupervisorDrainHostRunEscalationKind::from_label(expected_label),
                Some(kind)
            );
            assert_eq!(kind.rank(), expected_rank);
            assert_eq!(kind.to_string(), expected_label);
            assert_eq!(
                kind.is_settled(),
                matches!(kind, ToolAuditSupervisorDrainHostRunEscalationKind::Settled)
            );
            assert_eq!(
                kind.requires_action(),
                !matches!(kind, ToolAuditSupervisorDrainHostRunEscalationKind::Settled)
            );
        }

        assert!(ToolAuditSupervisorDrainHostRunEscalationKind::RoutineAction.is_auto_routable());
        assert!(
            ToolAuditSupervisorDrainHostRunEscalationKind::ManualReview.requires_manual_review()
        );
        assert!(
            ToolAuditSupervisorDrainHostRunEscalationKind::Investigation.requires_investigation()
        );
        assert!(
            ToolAuditSupervisorDrainHostRunEscalationKind::IntegrityInvestigation
                .requires_integrity_investigation()
        );
        assert!(ToolAuditSupervisorDrainHostRunEscalationKind::Triage.requires_triage());
        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationKind::from_label("unknown"),
            None
        );
    }

    #[test]
    fn supervisor_drain_host_run_escalation_digests_are_stable() {
        let supervision_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::HealthDashboardActionAndSchedulerAction,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::SplitQueues,
                ToolAuditSupervisorDrainHostRunActionLane::Mixed,
                ToolAuditSupervisorDrainHostRunQueuePriority::Triage,
                ToolAuditSupervisorDrainHostRunQueueReadiness::TriageRequired,
            ),
        );
        let digest = ToolAuditSupervisorDrainHostRunEscalationDigest::new(
            ToolAuditSupervisorDrainHostRunEscalationKind::Triage,
            supervision_key,
        );

        assert_eq!(
            digest.label(),
            "escalation=triage|supervision=attention=health_dashboard_action_and_scheduler_action|queue=split_queues:mixed:triage:triage_required"
        );
        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationDigest::from_label(&digest.label()),
            Some(digest)
        );
        assert!(digest.label_matches_digest());
        assert_eq!(
            digest.escalation_kind(),
            ToolAuditSupervisorDrainHostRunEscalationKind::Triage
        );
        assert_eq!(digest.supervision_key(), supervision_key);
        assert!(
            digest.escalation_kind_matches(ToolAuditSupervisorDrainHostRunEscalationKind::Triage)
        );
        assert!(digest.supervision_key_matches(supervision_key));
        assert!(digest.parts_match(
            ToolAuditSupervisorDrainHostRunEscalationKind::Triage,
            supervision_key,
        ));
        assert!(!digest.is_settled());
        assert!(digest.requires_action());
        assert_eq!(digest.priority_rank(), 90);
        assert!(!digest.is_auto_routable());
        assert!(digest.requires_manual_review());
        assert!(!digest.requires_investigation());
        assert!(!digest.requires_integrity_investigation());
        assert!(digest.requires_triage());
        assert_eq!(digest.to_string(), digest.label());

        let routine_supervision_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::HealthDashboardAction,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::HealthDashboard,
                ToolAuditSupervisorDrainHostRunActionLane::Drain,
                ToolAuditSupervisorDrainHostRunQueuePriority::RoutineAction,
                ToolAuditSupervisorDrainHostRunQueueReadiness::RoutineReady,
            ),
        );
        let routine_digest = ToolAuditSupervisorDrainHostRunEscalationDigest::new(
            ToolAuditSupervisorDrainHostRunEscalationKind::RoutineAction,
            routine_supervision_key,
        );
        assert!(routine_digest.is_auto_routable());
        assert_eq!(routine_digest.priority_rank(), 20);

        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationDigest::from_label(
                "escalation=triage|supervision=attention=no_attention|queue=no_route:no_action:settled:settled:extra",
            ),
            None
        );
        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationDigest::from_label(
                "escalationish=triage|supervision=attention=no_attention|queue=no_route:no_action:settled:settled",
            ),
            None
        );
    }

    #[test]
    fn supervisor_drain_host_run_escalation_routes_are_stable() {
        let supervision_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::NoAttention,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::NoRoute,
                ToolAuditSupervisorDrainHostRunActionLane::NoAction,
                ToolAuditSupervisorDrainHostRunQueuePriority::Settled,
                ToolAuditSupervisorDrainHostRunQueueReadiness::Settled,
            ),
        );
        let cases = [
            (
                ToolAuditSupervisorDrainHostRunEscalationKind::Settled,
                ToolAuditSupervisorDrainHostRunEscalationRoute::NoRoute,
                "no_route",
                false,
                false,
                false,
                false,
                false,
                false,
            ),
            (
                ToolAuditSupervisorDrainHostRunEscalationKind::RoutineAction,
                ToolAuditSupervisorDrainHostRunEscalationRoute::RoutineAction,
                "routine_action",
                true,
                true,
                false,
                false,
                false,
                false,
            ),
            (
                ToolAuditSupervisorDrainHostRunEscalationKind::ManualReview,
                ToolAuditSupervisorDrainHostRunEscalationRoute::ManualReview,
                "manual_review",
                true,
                false,
                true,
                false,
                false,
                false,
            ),
            (
                ToolAuditSupervisorDrainHostRunEscalationKind::Investigation,
                ToolAuditSupervisorDrainHostRunEscalationRoute::Investigation,
                "investigation",
                true,
                false,
                true,
                true,
                false,
                false,
            ),
            (
                ToolAuditSupervisorDrainHostRunEscalationKind::IntegrityInvestigation,
                ToolAuditSupervisorDrainHostRunEscalationRoute::IntegrityInvestigation,
                "integrity_investigation",
                true,
                false,
                true,
                true,
                true,
                false,
            ),
            (
                ToolAuditSupervisorDrainHostRunEscalationKind::Triage,
                ToolAuditSupervisorDrainHostRunEscalationRoute::Triage,
                "triage",
                true,
                false,
                true,
                false,
                false,
                true,
            ),
        ];

        for (
            kind,
            route,
            label,
            has_route,
            auto_routable,
            manual_review,
            investigation,
            integrity_investigation,
            triage,
        ) in cases
        {
            let digest =
                ToolAuditSupervisorDrainHostRunEscalationDigest::new(kind, supervision_key);

            assert_eq!(
                ToolAuditSupervisorDrainHostRunEscalationRoute::from_escalation_kind(kind),
                route
            );
            assert_eq!(
                ToolAuditSupervisorDrainHostRunEscalationRoute::from_digest(digest),
                route
            );
            assert_eq!(
                ToolAuditSupervisorDrainHostRunEscalationRoute::from_label(label),
                Some(route)
            );
            assert_eq!(route.as_str(), label);
            assert!(route.label_matches_route());
            assert_eq!(route.escalation_kind(), kind);
            assert!(route.escalation_kind_matches(kind));
            assert!(route.digest_matches(digest));
            assert_eq!(route.has_route(), has_route);
            assert_eq!(route.is_settled(), !has_route);
            assert_eq!(route.requires_action(), has_route);
            assert_eq!(route.priority_rank(), kind.rank());
            assert_eq!(route.is_auto_routable(), auto_routable);
            assert_eq!(route.requires_manual_review(), manual_review);
            assert_eq!(route.requires_investigation(), investigation);
            assert_eq!(
                route.requires_integrity_investigation(),
                integrity_investigation
            );
            assert_eq!(route.requires_triage(), triage);
            assert_eq!(
                route.routes_to_routine_action(),
                matches!(
                    route,
                    ToolAuditSupervisorDrainHostRunEscalationRoute::RoutineAction
                )
            );
            assert_eq!(
                route.routes_to_manual_review(),
                matches!(
                    route,
                    ToolAuditSupervisorDrainHostRunEscalationRoute::ManualReview
                )
            );
            assert_eq!(
                route.routes_to_investigation(),
                matches!(
                    route,
                    ToolAuditSupervisorDrainHostRunEscalationRoute::Investigation
                )
            );
            assert_eq!(
                route.routes_to_integrity_investigation(),
                matches!(
                    route,
                    ToolAuditSupervisorDrainHostRunEscalationRoute::IntegrityInvestigation
                )
            );
            assert_eq!(
                route.routes_to_triage(),
                matches!(
                    route,
                    ToolAuditSupervisorDrainHostRunEscalationRoute::Triage
                )
            );
            assert_eq!(route.to_string(), label);
        }

        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationRoute::from_label("settled"),
            None
        );
    }

    #[test]
    fn supervisor_drain_host_run_escalation_route_keys_are_stable() {
        let supervision_key = ToolAuditSupervisorDrainHostRunSupervisionKey::new(
            ToolAuditSupervisorDrainHostRunAttentionKind::HealthDashboardActionAndSchedulerAction,
            ToolAuditSupervisorDrainHostRunQueueGroupKey::new(
                ToolAuditSupervisorDrainHostRunQueueRoute::SplitQueues,
                ToolAuditSupervisorDrainHostRunActionLane::Mixed,
                ToolAuditSupervisorDrainHostRunQueuePriority::Triage,
                ToolAuditSupervisorDrainHostRunQueueReadiness::TriageRequired,
            ),
        );
        let digest = ToolAuditSupervisorDrainHostRunEscalationDigest::new(
            ToolAuditSupervisorDrainHostRunEscalationKind::Triage,
            supervision_key,
        );
        let key = ToolAuditSupervisorDrainHostRunEscalationRouteKey::new(
            ToolAuditSupervisorDrainHostRunEscalationRoute::Triage,
            digest,
        );

        assert_eq!(
            key.label(),
            "route=triage|digest=escalation=triage|supervision=attention=health_dashboard_action_and_scheduler_action|queue=split_queues:mixed:triage:triage_required"
        );
        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationRouteKey::from_label(&key.label()),
            Some(key)
        );
        assert!(key.label_matches_key());
        assert_eq!(
            key.route(),
            ToolAuditSupervisorDrainHostRunEscalationRoute::Triage
        );
        assert_eq!(key.digest(), digest);
        assert!(key.route_matches(ToolAuditSupervisorDrainHostRunEscalationRoute::Triage));
        assert!(key.digest_matches(digest));
        assert!(key.route_matches_digest());
        assert!(key.parts_match(
            ToolAuditSupervisorDrainHostRunEscalationRoute::Triage,
            digest,
        ));
        assert!(!key.is_settled());
        assert!(key.requires_action());
        assert_eq!(key.priority_rank(), 90);
        assert!(!key.is_auto_routable());
        assert!(key.requires_manual_review());
        assert!(!key.requires_investigation());
        assert!(!key.requires_integrity_investigation());
        assert!(key.requires_triage());
        assert!(key.has_route());
        assert_eq!(key.to_string(), key.label());

        let stale_key = ToolAuditSupervisorDrainHostRunEscalationRouteKey::new(
            ToolAuditSupervisorDrainHostRunEscalationRoute::NoRoute,
            digest,
        );
        assert!(!stale_key.route_matches_digest());
        assert!(stale_key.parts_match(
            ToolAuditSupervisorDrainHostRunEscalationRoute::NoRoute,
            digest,
        ));

        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationRouteKey::from_label(
                "route=triage|digest=escalation=unknown|supervision=attention=no_attention|queue=no_route:no_action:settled:settled",
            ),
            None
        );
        assert_eq!(
            ToolAuditSupervisorDrainHostRunEscalationRouteKey::from_label(
                "routeish=triage|digest=escalation=triage|supervision=attention=no_attention|queue=no_route:no_action:settled:settled",
            ),
            None
        );
    }

